import re
import sys

values = {}
assignment = re.compile(
    r"\s*(\w+)\s*<-\s*(?:(\d+)|\(\s*(\w+)\s*\+\s*(\d+)\s*\)\s*mod\s*(\d+))\s*;\s*"
)

for line in sys.stdin:
    line = line.strip()
    if not line or line.startswith("//"):
        continue

    match = assignment.fullmatch(line)
    if not match:
        continue

    target, constant, source, increment, modulus = match.groups()
    if constant is not None:
        values[target] = int(constant)
    else:
        values[target] = (values[source] + int(increment)) % int(modulus)

print(f"a ?= {values['a']}; b ?= {values['b']}; TMP ?= {values['TMP']};")
